column243:
09/Mar/26 10:14 AM;schatter;enum Overridden {
    None,
    True,
    False
}

// TODO: technically this is now a javascript object, not a list of props. figure out how to represent that properly
export interface StatusIndicatorProps {
    binaryStatus: boolean
    signalFault: boolean
    signalLost: boolean
    signalOverridden: Overridden
}

/**
 * A status data row component that is used to visually represent the status of a system component.
 *
 * NOTE: This component must be used within the <Table> and <TableBody> parent components, as <TableRows> cannot
 * be rendered independently.
 *
 * @param \{string} title - Label of the system component.
 * @param \{ReactNode} children - Object containing the status to display
 * @returns \{JSX.Element} status data row.
 */
export default function StatusIndicator(\{ binaryStatus, signalFault, signalLost, signalOverridden }: StatusIndicatorProps) {
    // TODO: figure out how to get the "info" colored icons to be "disabled" = b1b2b5 (doesn't currently exist in the theme placeholder)
    // The default is signal lost visual
    var statusIcon = <Avatar sx=\{{ width: 6, height: 8, p: 1.35 }}><SensorsOffIcon color="primary"/></Avatar>
    if(signalLost) {
        statusIcon= <Avatar sx=\{{ width: 6, height: 8, p: 1.35 }}><SensorsOffIcon color="info"/></Avatar>
    }
    // If overridden, visual icon should represent what the signal has been overridden to
    else if(signalOverridden != 0) {
        if(signalOverridden == 1)
        {
            statusIcon = <CheckCircleIcon fontSize="medium" color="success"/>
        }
        else if(signalOverridden == 2)
        {
            statusIcon = <CheckCircleIcon fontSize="medium" color="info"/>
        }
    }
    else if(signalFault) {
        statusIcon = <CancelIcon fontSize="medium" color="error"/>
    }
    else if(binaryStatus) {
        statusIcon = <CheckCircleIcon fontSize="medium" color="success"/>
    }
    // Only set to grey checkmark if binary status is false AND everything else is also false
    else if(!binaryStatus && !signalFault && !signalLost && signalOverridden == 0) {
        statusIcon = <CheckCircleIcon fontSize="medium" color="info"/>
    }    
 
 
 
 
 
^all of this processing logic is getting moved up to the TCS sidebar component. Status Indicator will now just be a map that renders the visual;;;

